import React, { useEffect, useRef, useState, useCallback } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import RecordRTC from 'recordrtc';

const GlbTest = () => {
  // ... (previous state and refs remain the same)
  const [isRecording, setIsRecording] = useState(false);
  const recordingTimerRef = useRef(null);

  // ... (previous useEffect, loadModel, updateCameraView functions remain the same)

  const toggleRecording = () => {
    if (isRecording) {
      stopRecording();
    } else {
      startRecording();
    }
  };

  const startRecording = async () => {
    const canvas = hiddenRendererRef.current.domElement;
    let newRecorder;

    if (!canvas.captureStream && !canvas.mozCaptureStream) {
      console.error('Canvas capture is not supported on this browser.');
      return;
    }

    const stream = canvas.captureStream ? canvas.captureStream(30) : canvas.mozCaptureStream(30);
    newRecorder = new RecordRTC(stream, {
      type: 'video',
      mimeType: 'video/mp4',
      bitsPerSecond: 800000  
    });

    newRecorder.startRecording();
    toggleAnimation(); // Start animation
    setRecorder(newRecorder);
    setIsRecording(true);

    // Set a timer to stop recording after 3 seconds
    recordingTimerRef.current = setTimeout(() => {
      stopRecording();
    }, 3000);
  };

  const stopRecording = () => {
    if (recordingTimerRef.current) {
      clearTimeout(recordingTimerRef.current);
    }

    recorder.stopRecording(() => {
      let blob = recorder.getBlob();
      setRecordingBlob(blob); // Save the blob for sharing
      toggleAnimation(); // Stop animation
      setIsRecording(false);
    });
  };

  const shareRecording = async () => {
    if (!recordingBlob) return;

    // Copy "Hello World!" to clipboard
    await navigator.clipboard.writeText('Hello World!');
    alert('"Hello World!" has been copied to your clipboard.');

    const file = new File([recordingBlob], 'animation.mp4', { type: 'video/mp4' });

    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({
          files: [file],
          title: 'My Animation',
          text: 'Check out this animation I created!',
        });
        console.log('Video shared successfully!');
      } catch (error) {
        console.error('Error sharing video:', error);
      }
    } else {
      const url = URL.createObjectURL(recordingBlob);
      const a = document.createElement('a');
      a.style.display = 'none';
      a.href = url;
      a.download = 'animation.mp4';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      console.log('Video downloaded successfully!');
    }
  };

  // ... (rest of the component remains the same)

  return (
    <div>
      {/* ... (previous JSX remains the same) */}
      <button 
        onClick={toggleRecording}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          fontSize: '14px',
          backgroundColor: isRecording ? 'red' : 'green',
          color: 'white',
          border: 'none',
          borderRadius: '5px',
          cursor: 'pointer'
        }}
      >
        {isRecording ? 'Stop Recording' : 'Start Recording'}
      </button>
      <button 
        onClick={shareRecording}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          fontSize: '14px',
          backgroundColor: 'blue',
          color: 'white',
          border: 'none',
          borderRadius: '5px',
          cursor: 'pointer'
        }}
        disabled={!recordingBlob}
      >
        Share Recording
      </button>
      {/* ... (rest of the JSX remains the same) */}
    </div>
  );
};

export default GlbTest;
